      "model_assumption": "chọn AC nằm trên trục Oy, AC vuông góc AB và AD",
      "source_fact_id": "ac_length"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 0, 2],
      "model_assumption": "chọn AD nằm trên trục Oz, AD vuông góc AB và AC",
      "source_fact_id": "ad_length"
    },
    {
      "kind": "construct_solid",
      "target_var": "ABCD_tu_dien",
      "vertices": ["A", "B", "C", "D"],
      "faces": [
        ["A", "B", "C"],
        ["A", "B", "D"],
        ["A", "C", "D"],
        ["B", "C", "D"]
      ],
      "source_fact_id": "abcd_tu_dien"
    },
    {
      "kind": "assign",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "B",
        "b": "C"
      },
      "source_fact_id": "m_trung_diem_bc"
    },
    {
      "kind": "construct_plane",
      "target_var": "plane_BCD",
      "through": ["B", "C", "D"],
      "label": "Mặt phẳng (BCD)"
    },
    {
      "kind": "assign",
      "target_var": "H",
      "expr": {
        "kind": "project_onto",
        "point": "A",
        "target": "plane_BCD"
      },
      "source_fact_id": "h_hinh_chieu_a_bcd"
    },
    {
      "kind": "construct_line",
      "target_var": "AM",
      "through_a": "A",
      "through_b": "M",
      "label": "Đường thẳng AM"
    },
